css_new=css_anchor+'''  #roomTopStatus.hider{color:#efceff;border-color:#6e4f7d;background:#281b30}\n  #roomTopStatus.seeker{color:#cbe3ff;border-color:#4e6480;background:#172535}\n  .objectiveCard{border-color:#49586a;background:linear-gradient(180deg,#222b35,#1c232c);padding:14px}\n  .objectiveCard.hider{border-color:#6e4f7d;background:linear-gradient(180deg,#2a2032,#211a28)}\n  .objectiveCard.seeker{border-color:#4e6480;background:linear-gradient(180deg,#1c2a39,#19232f)}\n  .objectiveCard.urgent{border-color:#9a5960;background:linear-gradient(180deg,#342126,#281a1d)}\n  .objectiveEyebrow{font-size:10px;font-weight:900;letter-spacing:1.2px;color:#aeb8c5;text-transform:uppercase}\n  .objectiveTitle{font-size:25px;font-weight:900;line-height:1.08;margin-top:5px}\n  .objectiveTimer{font-size:38px;font-weight:900;letter-spacing:1px;margin:7px 0 3px;color:#ffd8d8}\n  .objectiveMeta{display:flex;gap:7px;flex-wrap:wrap;margin-top:11px}\n  .statusChip{font-size:11px;font-weight:800;padding:5px 8px;border:1px solid #435064;border-radius:999px;background:#171d25;color:#dbe3ec}\n  .compactSection{padding:10px 12px}\n  .compactSection h3{margin-bottom:7px}\n  .secondaryTimer{display:none!important}\n  .moreGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n  .moreGrid button{text-align:left;padding:12px}\n  .moreGrid b{display:block;font-size:13px;margin-bottom:3px}\n  .moreGrid span{display:block;font-size:11px;color:var(--muted);line-height:1.3}\n  .questionCard.locked>label,.questionCard.locked>select,.questionCard.locked>input,.questionCard.locked>button,.questionCard.locked>p,.questionCard.locked>.validation,.questionCard.locked>div:not(.questionCost):not(.lockNotice){display:none!important}\n  .questionCard.locked{padding-bottom:9px}\n  .questionCard.locked .lockNotice{margin-bottom:0}\n  .settingsGroup{background:var(--panel2);border:1px solid #303947;border-radius:11px;margin-bottom:9px;overflow:hidden}\n  .settingsGroup>summary{list-style:none;cursor:pointer;padding:12px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;font-weight:850}\n  .settingsGroup>summary::-webkit-details-marker{display:none}\n  .settingsGroup>summary:after{content:'＋';font-size:17px;color:#aeb8c5}\n  .settingsGroup[open]>summary:after{content:'−'}\n  .settingsGroup[open]>summary{border-bottom:1px solid #303947}\n  .settingsHint{font-size:10px;font-weight:600;color:var(--muted);margin-left:auto}\n  .settingsBody{padding:12px}\n  .historyGroup{background:var(--panel2);border:1px solid #303947;border-radius:11px;margin-bottom:11px;overflow:hidden}\n  .historyGroup>summary{cursor:pointer;padding:11px 12px;font-size:13px;font-weight:800}\n  .historyBody{padding:0 12px 12px}\n  #liveLocationSection.liveConnected .liveLocationExtra{display:none}\n'''
