# Expandable Settings categories
settings_start=s.index('    <div id="view-settings" class="panelView">')
settings_end=s.index('    <div id="view-changelog" class="panelView">',settings_start)
settings=s[settings_start:settings_end]
settings_hints={
    'Question timing':'Unlock schedule + cooldown',
    'Forced relocation':'Cadence + movement target',
    'Map display':'Grid, towers, landmarks',
    'Sound':'Volume + gameplay cues',
    'Development / testing':'Testing-only controls',
    'Tower data':'Reference coordinates',
    'Landmark data':'Reference coordinates',
}
for title,hint in settings_hints.items():
    pattern=re.compile(r'      <section>\n        <h3>'+re.escape(title)+r'</h3>\n(.*?)      </section>',re.S)
    m=pattern.search(settings)
    if not m:
        raise SystemExit(f'settings group not found: {title}')
    body=m.group(1)
    repl=(f'      <details class="settingsGroup">\n'
          f'        <summary><span>{title}</span><span class="settingsHint">{hint}</span></summary>\n'
          f'        <div class="settingsBody">\n{body}'
          f'        </div>\n'
          f'      </details>')
    settings=settings[:m.start()]+repl+settings[m.end():]
s=s[:settings_start]+settings+s[settings_end:]

