# --- JS dashboard helpers ---
format_anchor='''function formatTime(totalSeconds){\n  totalSeconds=Math.max(0,Math.floor(totalSeconds));\n  const m=Math.floor(totalSeconds/60),s=totalSeconds%60;\n  return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;\n}\n'''
helpers=format_anchor+'''function formatApproxDuration(totalSeconds){\n  totalSeconds=Math.max(0,Number(totalSeconds)||0);\n  if(totalSeconds<=1)return "now";\n  if(totalSeconds<60)return "<1 min";\n  const m=Math.max(1,Math.ceil(totalSeconds/60));\n  return `~${m} min`;\n}\nfunction nextQuestionUnlockInfo(sec=currentMatchSeconds()){\n  const list=[[unlockTimes.grid,"Centerline"],[unlockTimes.nearest,"Nearest tower"],[unlockTimes.towerRadius,"Tower radius"],[unlockTimes.landmark,"Landmark questions"],[unlockTimes.marker,"Marker questions"]];\n  const next=list.find(([t])=>sec<Number(t));\n  return next?`${next[1]} unlocks ${formatApproxDuration(Number(next[0])-sec)}`:"All question types unlocked";\n}\nfunction updateTopRoleBadge(){\n  const badge=document.getElementById("roomTopStatus");if(!badge)return;\n  badge.classList.remove("hider","seeker");\n  if(!roomModeConnected()){badge.textContent="OFFLINE";return;}\n  const role=roomRole(),code=window.BigWalkRooms?.getRoomCode?.()||"ROOM";\n  badge.textContent=`${role==="hider"?"HIDER":"SEEKER"} · ${code}`;\n  badge.classList.add("connected",role==="hider"?"hider":"seeker");\n}\nfunction updateGameDashboard(){\n  const card=document.getElementById("currentActionSection");if(!card)return;\n  const eyebrow=document.getElementById("currentActionEyebrow"),title=document.getElementById("currentActionTitle"),timer=document.getElementById("currentActionTimer"),detail=document.getElementById("currentActionDetail"),next=document.getElementById("currentActionNext"),secondary=document.getElementById("currentActionSecondary");\n  const controls=document.getElementById("matchControlSection"),points=document.getElementById("seekerPointsSection"),qSection=document.getElementById("questionNextSection"),qStatus=document.getElementById("gameQuestionStatus"),qNext=document.getElementById("gameQuestionNext");\n  const connected=roomModeConnected(),role=connected?roomRole():null,isHider=role==="hider",isSeeker=role==="seeker",sec=currentMatchSeconds(),running=connected?roomMatchRunning():matchRunning;\n  controls.style.display=connected&&!window.BigWalkRooms?.isHost?.()?"none":"block";\n  points.style.display=isSeeker?"block":"none";qSection.style.display=isSeeker?"block":"none";\n  card.classList.remove("hider","seeker","urgent");if(isHider)card.classList.add("hider");if(isSeeker)card.classList.add("seeker");\n  timer.style.display="none";eyebrow.textContent="CURRENT STATUS";\n  const relocationNext=Math.max(0,Number(relocationState.nextAt??relocationSettings.firstAt)-sec);\n  next.textContent=missionState.active?"Relocation · paused":`Next relocation · ${formatApproxDuration(relocationNext)}`;\n  secondary.textContent=isHider?`⚡ ${Math.max(0,Number(hiderPowerCharges||0))} Power Charge${Number(hiderPowerCharges||0)===1?"":"s"}`:isSeeker?`${seekerPointsBalance()} Seeker Point${seekerPointsBalance()===1?"":"s"}`:"—";\n  if(!connected){title.textContent="Join a room";detail.textContent="Create or join a shared room to start a multiplayer match.";next.textContent="No active match";secondary.textContent="—";return;}\n  if(sec<.01&&!running){title.textContent="Ready to play";detail.textContent=window.BigWalkRooms?.isHost?.()?"Start the match when everyone is ready.":"Waiting for the room host to start the match.";next.textContent="Match not started";return;}\n  if(!running){title.textContent="Match paused";detail.textContent="Gameplay timers are paused.";next.textContent="Waiting to resume";return;}\n  if(relocationState.active){\n    card.classList.add("urgent");eyebrow.textContent="CURRENT OBJECTIVE";\n    const rem=Math.max(0,Number(relocationState.deadline||sec)-sec);timer.style.display="block";timer.textContent=rem>0?formatTime(rem):"OVERTIME";\n    title.textContent=isHider?"Forced relocation":"Hider relocating";\n    if(isHider&&localRelocationPlan&&!localRelocationPlan.invalid&&!localRelocationPlan.skip&&liveMarker){\n      const d=Math.hypot(liveMarker.x-localRelocationPlan.start.x,liveMarker.y-localRelocationPlan.start.y);detail.textContent=`${Math.round(d)} / ${Math.round(localRelocationPlan.target)} units from relocation start.`;\n    }else detail.textContent=isHider?"Move to a legal new hiding area and press Ready when the target is met.":"Questions are locked until the Hider finishes relocating.";\n    next.textContent=rem>0?"Target window active":"Overtime penalty active";return;\n  }\n  if(missionState.active){\n    eyebrow.textContent="CURRENT OBJECTIVE";title.textContent=isHider?"Cross the Zone":"Hider mission active";\n    if(isHider&&liveMarker&&localHiderMissionPlan&&!localHiderMissionPlan.invalid){const d=missionDistanceToTarget(liveMarker,localHiderMissionPlan);detail.textContent=Number.isFinite(d)?`${Math.max(0,Math.round(d))} units to the purple target area.`:"Reach the private purple target area.";}\n    else detail.textContent=isHider?"Reach the private purple target area.":"The mission target and Hider progress remain private.";\n    next.textContent="Forced relocation · paused";return;\n  }\n  if(isHider&&missionState.available){eyebrow.textContent="OPTIONAL OBJECTIVE";title.textContent="Mission available";detail.textContent="Cross the Zone is ready whenever you want to take it.";return;}\n  title.textContent=isHider?"Stay hidden":"Search for the Hider";\n  detail.textContent=isHider?"No movement objective is active. Stay put unless you choose a mission.":questionCooldownActive()?"An unlocked question is cooling down.":"Use the map and spend points on available questions.";\n  if(isSeeker){\n    if(relocationState.active)qStatus.textContent="Locked";\n    else if(questionCooldownActive())qStatus.textContent=`Cooling down · ${formatApproxDuration(questionCooldownRemaining())}`;\n    else qStatus.textContent="Ready";\n    qNext.textContent=nextQuestionUnlockInfo(sec)+".";\n  }\n}\n'''
once(format_anchor,helpers,'dashboard helpers')

